import React, { useState } from 'react';
import ResetPasswordModal from './ResetPasswordModal';

export default function StudentDashboard({ userName, handleLogout }) {
  const [showResetModal, setShowResetModal] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // 🟢 Aura Pen Saku ආයතනයේ ළමයා යන පන්ති ලිස්ට් එක
  const enrolledClasses = [
    { id: 1, grade: "Grade 11", subject: "Maths (Sinhala)", teacher: "Buddhika Darshani", progress: 85, color: "#15803d" },
    { id: 2, grade: "Grade 11", subject: "Science", teacher: "Ravindu Jayaweera", progress: 60, color: "#3b82f6" },
    { id: 3, grade: "Grade 11", subject: "English", teacher: "Ranga Rajaguru", progress: 45, color: "#f59e0b" },
    { id: 4, grade: "Grade 11", subject: "Commerce", teacher: "Sankalpa Suresh", progress: 75, color: "#8b5cf6" }
  ];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            
            {/* 🟢 Welcome Banner & Star Badges */}
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '25px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 4px 15px rgba(21,128,61,0.2)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'relative', zIndex: 2 }}>
                <h1 style={{ margin: '0 0 8px 0', fontSize: '28px' }}>Welcome back, {userName || 'Kasun'}! 👋</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Your Aura Pen Saku Learning Portal is ready.</p>
              </div>
              
              <div style={{ position: 'relative', zIndex: 2, backgroundColor: 'rgba(255,255,255,0.15)', padding: '15px 25px', borderRadius: '12px', textAlign: 'center', backdropFilter: 'blur(5px)', border: '1px solid rgba(255,255,255,0.3)' }}>
                <h3 style={{ margin: '0 0 5px 0', color: '#facc15', fontSize: '22px', letterSpacing: '2px' }}>⭐⭐⭐</h3>
                <p style={{ margin: 0, fontSize: '13px', fontWeight: 'bold' }}>3 Star Badges Earned!</p>
              </div>
              {/* Background Watermark */}
              <div style={{ position: 'absolute', right: '150px', top: '-40px', fontSize: '150px', opacity: 0.1, zIndex: 1 }}>🎓</div>
            </div>

            {/* 🟢 Overall Stats */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Video Lessons" count="12" icon="▶️" color="#eff6ff" textColor="#3b82f6" />
              <DashboardCard title="PDF Handouts" count="08" icon="📄" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Completed Activities" count="05" icon="✅" color="#fefce8" textColor="#eab308" />
            </div>

            {/* 🟢 My Enrolled Classes (Progress Bars එක්ක) */}
            <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '20px' }}>📚 My Enrolled Classes</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
              {enrolledClasses.map(cls => (
                <div key={cls.id} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid ${cls.color}`, display: 'flex', flexDirection: 'column' }}>
                  <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{cls.grade} • {cls.teacher}</div>
                  <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '18px' }}>{cls.subject}</h3>
                  
                  <div style={{ marginBottom: '20px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <span style={{ fontSize: '12px', color: '#64748b', fontWeight: 'bold' }}>Course Progress</span>
                      <span style={{ fontSize: '12px', color: cls.color, fontWeight: 'bold' }}>{cls.progress}%</span>
                    </div>
                    <div style={{ width: '100%', height: '6px', backgroundColor: '#f1f5f9', borderRadius: '3px', overflow: 'hidden' }}>
                      <div style={{ width: `${cls.progress}%`, height: '100%', backgroundColor: cls.color, borderRadius: '3px' }}></div>
                    </div>
                  </div>

                  <button onClick={() => setActiveTab('lessons')} style={{ width: '100%', padding: '10px', backgroundColor: '#f8fafc', color: '#1e293b', border: '1px solid #e2e8f0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', transition: '0.2s' }}>
                    📂 Enter Class
                  </button>
                </div>
              ))}
            </div>
          </div>
        );

      case 'lessons':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>📺 Video Lessons & Materials</h2>
            <div style={{ display: 'flex', gap: '25px', flexWrap: 'wrap' }}>
                <div style={{ flex: '2 1 500px', backgroundColor: '#000', height: '400px', borderRadius: '15px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', color: 'white', boxShadow: '0 10px 30px rgba(0,0,0,0.15)', position: 'relative' }}>
                    <span style={{ fontSize: '60px', color: '#ef4444', cursor: 'pointer' }}>▶️</span>
                    <p style={{ marginTop: '15px', fontSize: '15px', opacity: 0.8 }}>Select a lesson to start playing</p>
                </div>
                <div style={{ flex: '1 1 300px', backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 20px 0', color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>Current Lesson Materials</h3>
                    
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                      <div style={materialCardStyle}>
                        <div style={{ fontSize: '24px' }}>📄</div>
                        <div><div style={{ fontWeight: 'bold', fontSize: '14px', color: '#1e293b' }}>Lesson Note 01</div><div style={{ fontSize: '12px', color: '#64748b' }}>PDF • 2.4 MB</div></div>
                        <button style={downloadBtnStyle}>⬇️</button>
                      </div>
                      
                      <div style={materialCardStyle}>
                        <div style={{ fontSize: '24px' }}>📄</div>
                        <div><div style={{ fontWeight: 'bold', fontSize: '14px', color: '#1e293b' }}>Tutorial 01</div><div style={{ fontSize: '12px', color: '#64748b' }}>PDF • 1.1 MB</div></div>
                        <button style={downloadBtnStyle}>⬇️</button>
                      </div>
                    </div>

                    <button style={{...actionBtnStyle, backgroundColor: '#eab308', color: '#fff', marginTop: '30px', boxShadow: '0 4px 10px rgba(234,179,8,0.3)'}}>
                      📝 Take MCQ Quiz Now
                    </button>
                </div>
            </div>
          </div>
        );

      case 'activities':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>🎮 Interactive Learning Module</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
                <div style={activityCardStyle}>
                    <div style={{ fontSize: '40px', marginBottom: '15px' }}>🧩</div>
                    <h3 style={{ margin: '0 0 10px 0', color: '#1e293b' }}>Matching Game</h3>
                    <p style={{ color: '#64748b', fontSize: '14px', lineHeight: '1.5', marginBottom: '20px' }}>Match the subject terms with their correct definitions to earn badges.</p>
                    <button style={actionBtnStyle}>Start Game ▶️</button>
                </div>
                <div style={activityCardStyle}>
                    <div style={{ fontSize: '40px', marginBottom: '15px' }}>✍️</div>
                    <h3 style={{ margin: '0 0 10px 0', color: '#1e293b' }}>Fill-in-the-Blanks</h3>
                    <p style={{ color: '#64748b', fontSize: '14px', lineHeight: '1.5', marginBottom: '20px' }}>Complete the sentences based on this week's video lessons.</p>
                    <button style={actionBtnStyle}>Start Activity ▶️</button>
                </div>
            </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 Sidebar */}
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', boxShadow: '4px 0 15px rgba(0,0,0,0.1)' }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px', letterSpacing: '1px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'lessons'} onClick={() => setActiveTab('lessons')} icon="📺" text="My Lessons" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🎮" text="Interactive Games" />
          <SidebarBtn active={false} onClick={() => setShowResetModal(true)} icon="🔑" text="Change Password" />
        </div>
        <div style={{ marginTop: 'auto', padding: '0 15px' }}>
          <button onClick={handleLogout} style={logoutBtnStyle}>🚪 Logout</button>
        </div>
      </div>

      {/* 🟢 Main Content Area */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {renderContent()}
      </div>

      {showResetModal && <ResetPasswordModal userName={userName} role="student" setShowResetModal={setShowResetModal} />}
    </div>
  );
}

// 🟢 Reusable Components & Styles
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}`, boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
    <div>
      <p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p>
      <h3 style={{ margin: 0, color: '#1e293b', fontSize: '28px' }}>{count}</h3>
    </div>
    <div style={{ width: '55px', height: '55px', borderRadius: '12px', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '24px' }}>{icon}</div>
  </div>
);

const materialCardStyle = { display: 'flex', alignItems: 'center', gap: '15px', padding: '15px', border: '1px solid #e2e8f0', borderRadius: '10px', backgroundColor: '#f8fafc' };
const downloadBtnStyle = { marginLeft: 'auto', background: 'none', border: 'none', cursor: 'pointer', fontSize: '20px', padding: '5px' };
const actionBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '14px', transition: '0.2s' };
const activityCardStyle = { backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', border: '1px solid #f1f5f9', display: 'flex', flexDirection: 'column', alignItems: 'flex-start' };
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: 'rgba(239,68,68,0.2)', color: '#fca5a5', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px', transition: '0.2s' };
